# -*- coding: utf-8 -*-
"""Hayır Deme Cümleleri: 60 hazır mesaj (no: (durum, mesaj, geri bastırırsa))."""
MESAJLAR = {
    '01': ('Annen hafta sonu yemeğe çağırıyor, sen yorgunsun.', 'Anneciğim bu hafta sonu gelemeyeceğim, dinlenmem lazım. Haftaya cumartesi geleyim, o gün sana ayırıyorum.', 'Biliyorum üzüldün. Bu hafta olmuyor, haftaya görüşüyoruz.'),
    '02': ('Baban bir konuda sürekli akıl veriyor.', 'Baba, düşündüğün için teşekkür ederim. Bu konuda kararımı verdim, şimdi desteğine ihtiyacım var, fikre değil.', 'Kararım değişmedi. Konuyu burada kapatalım istiyorum.'),
    '03': ('Aile grubunda sana düşen bir organizasyon işi var, yine sen bekleniyorsun.', 'Bu sefer organizasyonu ben üstlenmiyorum. Kim alırsa ona yardım ederim ama baş sorumlu olmayacağım.', 'Evet, bu sefer ben değil. Kimse almazsa yapılmaz, o da olur.'),
    '04': ('Kardeşin sürekli çocuğuna bakmanı istiyor.', 'Bu hafta bakamayacağım. Kendi programımı ancak toparladım. Önceden haber verirsen ayda bir gün ayarlayabilirim.', 'Bu hafta olmuyor. Başka bir çözüm bulman gerekiyor.'),
    '05': ('Bayramda herkes sende toplanmak istiyor.', 'Bu bayram evimde ağırlamıyorum. Dışarıda buluşalım ya da bu sefer başka bir evde olsun. Gelirim ama ev sahibi olmayacağım.', 'Kararımı verdim, bu bayram ev sahibi değilim.'),
    '06': ("Annen 'bana vakit ayırmıyorsun' diyor.", 'Seni seviyorum ve sana vakit ayırmak istiyorum. Her gün aramak yerine haftada iki gün uzun uzun konuşalım, bu bana daha iyi geliyor.', 'Haftada iki gün konuşacağız. Bu da sevgi.'),
    '07': ('Akraba düğününe gitmek istemiyorsun.', 'Düğüne katılamayacağım, ailecek çok mutlu olun. Hediyemi önceden göndereceğim.', 'Gelemiyorum. Tebrik ve hediyem sizinle.'),
    '08': ('Baban maddi konuda sana yüklenmeye devam ediyor.', 'Bu ay yardım edemeyeceğim, kendi bütçemi ancak dengeledim. Bunu söylemek zor ama gerçek bu.', 'Bu ay olmuyor. Lütfen tekrar sormayın, elimden geldiğinde ben söyleyeceğim.'),
    '09': ('Annen evine habersiz geliyor.', 'Seni görmek güzel ama habersiz gelince hazırlıksız oluyorum ve keyif alamıyorum. Bundan sonra gelmeden bir yazsan çok sevinirim.', 'Habersiz gelince kapıyı açmamayı seçebilirim, kırgınlık değil, ihtiyaç.'),
    '10': ('Aile grubundaki tartışmaya seni çekmek istiyorlar.', 'Bu tartışmanın parçası olmayacağım. İkinizi de seviyorum ve taraf tutmuyorum.', 'Konuyu benimle konuşmayın lütfen. Aranızda çözün.'),
    '11': ('Partnerin akşam planını sana sormadan yapmış.', 'Bu akşam gelmiyorum, bana sorulmadan plan yapılınca kendimi dahil hissetmiyorum. Sen git, keyifli olsun. Bir dahaki sefere önce bana sor.', 'Bu akşam yokum. Yarın konuşalım.'),
    '12': ('Ev işleri yine sende kalmış.', 'Bu hafta çamaşır ve bulaşık sende. Ben yapmayacağım. Bu bir tartışma değil, bir paylaşım.', 'Hayır, ben yapmayacağım. Birikirse birikir.'),
    '13': ('Partnerin ailesine her hafta sonu gitmek istiyor.', 'Her hafta sonu ailene gitmek bana fazla geliyor. Ayda iki kez gelirim, diğer hafta sonları bize ayıralım.', 'Ayda iki. Bu benim için net.'),
    '14': ('Yorgunsun, yakınlık istemiyor.', 'Bu akşam yakınlık istemiyorum, sadece yorgunum. Seninle ilgili değil, sana sarılıp uyumak istiyorum.', 'Bu akşam hayır. Bu cümleyi açıklamak zorunda değilim.'),
    '15': ('Ortak para kararına seni dahil etmemiş.', 'Ortak paramızdan bana sormadan harcama yapılmasını kabul etmiyorum. Bundan sonra belli bir tutarın üstünü birlikte kararlaştıralım.', 'Bu kararı birlikte almadık, bu yüzden hayır.'),
    '16': ('Senden telefonunu göstermeni istiyor.', 'Telefonumu göstermeyeceğim. Saklayacak bir şeyim yok, mahremiyetim var. Güven, kontrolle kurulmuyor.', 'Hayır. Bu konuyu bir daha açmanı istemiyorum.'),
    '17': ('Kavgada seni haksız yere suçluyor, hemen cevap vermeni istiyor.', 'Şu an bu konuşmaya devam edemem. Sakinleşince, bu akşam dokuzda konuşalım.', 'Dokuzda. Şimdi değil.'),
    '18': ("Senin 'hallettiğin' bir işi doğal karşılıyor.", 'Bunu ben yaptım ve fark edilmesini istiyorum. Teşekkür beklemek bana kibir değil, ihtiyaç.', 'Görülmek istiyorum. Bu kadar.'),
    '19': ('Son dakika kahveye çağırıyor, halin yok.', 'Bugün gelemiyorum, enerjim yok. Perşembe nasıl?', 'Bugün olmuyor, perşembe görüşürüz.'),
    '20': ('Her görüşmede sadece o anlatıyor, dinlenmiyorsun.', 'Seni dinlemeyi seviyorum ama son zamanlarda ben konuşamıyorum. Bir dahaki buluşmada yarı yarıya olsun istiyorum.', 'Bu bana iyi gelmiyor, söylemek istedim.'),
    '21': ('Borç para istiyor.', 'Borç veremeyeceğim. Bunu arkadaşlığımızı korumak için söylüyorum; para araya girince bozuluyor.', 'Cevabım hayır. Başka nasıl yardım edebilirim, onu konuşalım.'),
    '22': ('Sürekli geç kalıyor.', 'On beş dakikadan fazla gecikirsen gidiyorum. Kızgın değilim, sadece zamanıma sahip çıkıyorum.', 'On beş dakika oldu, çıkıyorum. Bir dahaki sefere.'),
    '23': ('Grup tatiline katılmak istemiyorsun.', 'Bu tatile katılmıyorum. Sebep aramayın, bu sefer bana göre değil. İyi eğlenin, fotoğraf bekliyorum.', 'Katılmıyorum. Mesele yok, karar var.'),
    '24': ('Senin aracılığınla birine ulaşmak istiyor (iş, tanıdık).', 'Bu konuda aracı olmak istemiyorum. Kendi adıma referans vermek benim için ağır bir şey.', 'Hayır, aracı olmayacağım.'),
    '25': ('Dert ortağı olarak sadece seni kullanıyor, gece gündüz.', 'Seni önemsiyorum ve gece on birden sonra mesajlara bakmıyorum. Acilse ara, değilse sabah konuşuruz.', 'On birden sonra yokum. Sabah buradayım.'),
    '26': ('Düğününde görev vermek istiyor, istemiyorsun.', 'Düğününde görev almayacağım ama en önde alkışlayacağım. Bunu dert etme, sen güzelce evlen.', 'Görev yok, ben misafir olacağım.'),
    '27': ("Patron akşam altıda yeni bir iş veriyor, 'yarın sabah' diyor.", 'Bunu yarın sabah teslim edemem. Yarın öğleden sonra teslim edebilirim; daha erken gerekiyorsa X işini erteleyebiliriz, hangisini tercih edersiniz?', 'Yarın öğleden sonra. İkisi birden olmuyor.'),
    '28': ('Hafta sonu çalışman isteniyor.', 'Bu hafta sonu çalışamayacağım. Pazartesi ilk iş bununla başlarım.', 'Hafta sonu müsait değilim.'),
    '29': ('İş arkadaşın işini sana yıkıyor.', 'Bunu ben yapamayacağım, kendi işlerim var. Yetişmiyorsa yöneticine söylemen gerekiyor.', 'Hayır, bu senin işin. Yardım değil, devir istiyorsun.'),
    '30': ('Toplantıya gereksiz yere çağrılıyorsun.', 'Bu toplantıya katılmam gerekmiyor sanırım; notları paylaşırsanız gereken yerde devreye girerim.', 'Katılmıyorum, notları bekliyorum.'),
    '31': ('Müşteri kapsam dışı iş istiyor, bedava.', 'Bu talep anlaşmamızın dışında. Memnuniyetle yaparım, ek ücreti şu kadar. Onaylarsanız başlıyorum.', 'Ek ücretsiz yapamıyorum. Kararınızı bekliyorum.'),
    '32': ('Müşteri gece mesaj atıyor.', 'Mesajlarınızı iş saatlerinde yanıtlıyorum, dokuz ile altı arası. Acil durumlar için şu numaradan arayabilirsiniz.', 'Sabah dokuzda dönüş yapacağım.'),
    '33': ('Terfi vaadiyle fazla iş yükleniyor.', 'Ek sorumluluk almaya açığım ama yazılı bir plan olmadan değil. Unvan, tarih ve ücreti konuşalım, sonra başlayayım.', 'Yazılı olmadan ek yük almıyorum.'),
    '34': ("Ücretsiz 'küçük bir danışma' istiyorlar.", 'Bu konuda fikrim var ve bunu ücretli olarak sunuyorum. İsterseniz 45 dakikalık bir görüşme ayarlayalım.', 'Ücretsiz danışmanlık vermiyorum.'),
    '35': ("Eski iş yerinden 'bir el at' diyorlar.", 'Artık orada çalışmıyorum ve dışarıdan destek vermiyorum. Yeni ekibe güveniyorum, halledeceklerdir.', 'Hayır, bu artık benim işim değil.'),
    '36': ('Patron toplantıda seni kesiyor, sözünü bitirmek istiyorsun.', 'Sözümü bitirmek istiyorum, iki cümlem kaldı.', 'Bitirmeden geçmeyelim lütfen.'),
    '37': ('Performans görüşmesinde kabul etmediğin bir eleştiri var.', 'Bu değerlendirmeye katılmıyorum ve nedenlerimi yazılı olarak iletmek istiyorum. Kayda geçsin.', 'Katılmıyorum, yazılı itirazımı göndereceğim.'),
    '38': ("Sürekli 'sen hallediyorsun' diye sana verilen işler.", 'Her şeyi hallediyor olmam her şeyin bende olması gerektiği anlamına gelmiyor. Bu işi başkasına vermenizi istiyorum.', 'Bu iş bende olmayacak.'),
    '39': ('Veli grubunda sınıf annesi olman isteniyor.', 'Bu yıl sınıf annesi olamayacağım. Gönüllü olan arkadaşa ihtiyaç duyarsa yardım ederim.', 'Bu yıl ben değil.'),
    '40': ('Okul etkinliği için kek yapman bekleniyor.', 'Bu sefer kek yapamayacağım, hazır bir şey getireceğim.', 'Hazır getiriyorum, bu da katkı.'),
    '41': ('Komşu çocuğuna sık sık bakmanı istiyor.', 'Bugün bakamayacağım. Genel olarak da düzenli çocuk bakımı üstlenemiyorum, bunu bilmeni isterim.', 'Hayır, bakamıyorum.'),
    '42': ('Komşu her gün kapıya geliyor, sohbete.', 'Sohbetimizi seviyorum ama gün içinde çalışıyorum. Akşam altıdan sonra kapımı çalarsan daha rahat konuşuruz.', 'Şu an müsait değilim, akşam görüşürüz.'),
    '43': ("Akraba 'neden hâlâ çocuk yok / evlilik yok' diye soruyor.", 'Bu özel bir konu ve konuşmak istemiyorum. Sormamanı rica ediyorum.', 'Konuşmuyorum demiştim. Konuyu değiştirelim.'),
    '44': ('Veli grubundaki tartışmaya çağrılıyorsun.', 'Bu konuda görüş bildirmeyeceğim. Okulla doğrudan konuşmak isteyen konuşsun, ben gruba dahil olmuyorum.', 'Tarafsızım ve öyle kalacağım.'),
    '45': ('Apartman toplantısına yönetici olman için baskı var.', 'Yöneticilik yapamayacağım. Aidat ve toplantılara katılırım ama görev almıyorum.', 'Görev almıyorum, teşekkürler.'),
    '46': ('Birisi senin arabanla bir yere bırakmanı istiyor, sürekli.', 'Bugün bırakamayacağım, yolum ters. Genel olarak da şoförlük yapmayı bırakıyorum, haberin olsun.', 'Olmuyor, taksi ya da otobüs düşünebilirsin.'),
    '47': ("Tanıdık ürün satmaya çalışıyor, 'destek ol' diyor.", 'Ürünü almayacağım. Sana başarılar diliyorum, ama arkadaşlığımız alışverişe bağlı değil.', 'Almıyorum, konuyu kapatalım.'),
    '48': ('Daha önce verdiğin borç geri gelmedi, yenisini istiyor.', 'Önceki borç henüz dönmediği için yenisini veremem. Önce onu kapatalım, sonra konuşuruz.', 'Hayır. Önce eskisi.'),
    '49': ('Düğün, doğum günü, hediye toplama listesi uzayıp gidiyor.', 'Bu sefer katılmıyorum, bütçem bu ay buna uygun değil.', 'Katılmıyorum.'),
    '50': ("Biri senden 'kefil ol' istiyor.", 'Kefil olmayacağım. Bu bir güven meselesi değil, prensip; kimseye kefil olmuyorum.', 'Hayır, kefil olmam.'),
    '51': ('Bir hizmet sunuyorsun, indirim istiyorlar.', 'Fiyatım bu, indirim yapmıyorum. Bütçenize uygun daha küçük bir paket önerebilirim.', 'Fiyat sabit. Küçük paket seçeneği duruyor.'),
    '52': ('Kardeşin ortak miras konusunda baskı yapıyor.', 'Bu konuyu mesajla konuşmuyorum. Avukatla ya da yüz yüze, sakin bir ortamda konuşalım.', 'Mesajla değil. Tarih verin, yüz yüze.'),
    '53': ('Hastasın, yine de ziyaretçi kabul etmen bekleniyor.', 'Bugün ziyaretçi kabul etmiyorum, iyileşmem lazım. İyileşince haber vereceğim.', 'Ziyaret yok. Teşekkür ederim, iyileşince görüşürüz.'),
    '54': ("Yas tutuyorsun, insanlar 'güçlü ol' diyor ve soru soruyor.", 'Şu an konuşamıyorum. Yanımda olduğunu bilmek yeter, mesajlara dönemeyebilirim.', 'Bir süre sessiz kalacağım, sağlık olsun.'),
    '55': ("Tükendin, 'bir şey organize et' diyorlar.", 'Şu an organize edecek enerjim yok. Bu kez başkası üstlensin, ben katılırım.', 'Ben değil. Bu sefer gerçekten değil.'),
    '56': ('Doğum sonrası herkes bebeği görmeye geliyor.', 'İlk iki hafta ziyaretçi almıyoruz. Sonrasında gün ayarlayıp haber vereceğim.', 'İki hafta sonra. Anlayışınız için teşekkürler.'),
    '57': ("Terapide ya da bir süreçtesin, 'ne oldu' diye kurcalıyorlar.", 'Bir süreçten geçiyorum ve bunu paylaşmayı seçmiyorum. Sorulmaması bana iyi gelir.', 'Konuşmuyorum. Lütfen.'),
    '58': ('Herkese destek olan sensin, bu kez sana soran yok.', 'Bu kez benim desteğe ihtiyacım var. Bunu söylemek bana zor geliyor, o yüzden kısa yazdım.', 'Evet, bana ihtiyacım var dedim. Geri almıyorum.'),
    '59': ('Kendine. Suçluluk geldiğinde telefona bakmadan önce.', 'Hayır dedim. Kimse ölmedi. Suçluluk bir duygu, bir kanıt değil. Telefonu bırak.', 'Kararını verdin. Açıklama borcun yok.'),
    '60': ("Kendine. Hayır dedikten sonra 'ben kötü biri miyim' sorusu gelince.", 'İyi bir insan olmak için herkese evet demen gerekmiyor. Hayır da sevginin bir biçimi; kendine duyulan.', 'Hayır diyen kadın, kötü kadın değil. Dinlenen kadın.'),
}

def mesaj(no):
    return MESAJLAR.get(str(no).zfill(2))
